# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv_transpose2d_im2col_fold_forward(torch::Tensor input, torch::Tensor weight);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose2d_im2col_fold_forward", &conv_transpose2d_im2col_fold_forward, "Specialized ConvTranspose2d k3 s1 forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fold kernel: patches has shape [N*H*W, Cout*9], output has shape [N, Cout, H+2, W+2]
// Each thread handles one element of patches and does atomicAdd into output
__global__ void __launch_bounds__(256, 4) fold_patches_kernel(
    const float* __restrict__ patches,
    float* __restrict__ output,
    int N, int Cin, int Cout, int H_in, int W_in, int H_out, int W_out
) {
    // patches: [N*H_in*W_in, Cout*9]
    // We iterate over flattened index of [N*H_in*W_in * Cout * 9]
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * H_in * W_in * Cout * 9;
    if (idx >= total) return;

    int kw = idx % 3;
    int kh = (idx / 3) % 3;
    int co = (idx / 9) % Cout;
    int spatial = idx / (9 * Cout);  // in [0, N*H_in*W_in)
    int iw = spatial % W_in;
    int ih = (spatial / W_in) % H_in;
    int n  = spatial / (H_in * W_in);

    int oh = ih + kh;  // stride=1, padding=0: output = input_coord + kernel_coord
    int ow = iw + kw;

    float val = __ldg(&patches[spatial * (Cout * 9) + co * 9 + kh * 3 + kw]);

    int out_idx = ((n * Cout + co) * H_out + oh) * W_out + ow;
    atomicAdd(&output[out_idx], val);
}

torch::Tensor conv_transpose2d_im2col_fold_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(input.dim() == 4, "input must be 4D");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");
    TORCH_CHECK(weight.size(2) == 3 && weight.size(3) == 3, "kernel must be 3x3");

    const int N    = input.size(0);
    const int Cin  = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);
    const int Cout = weight.size(1);
    const int H_out = H_in + 2;  // stride=1, padding=0, k=3: H_out = H_in + k - 1 = H_in + 2
    const int W_out = W_in + 2;

    TORCH_CHECK(weight.size(0) == Cin, "weight input channels must match input");

    // input_flat: [N*H_in*W_in, Cin]
    auto input_flat = input.permute({0, 2, 3, 1}).contiguous().view({N * H_in * W_in, Cin});

    // weight_mat: [Cin, Cout*9]  (weight layout is [Cin, Cout, kH, kW])
    auto weight_mat = weight.view({Cin, Cout * 9});

    // patches: [N*H_in*W_in, Cout*9]
    auto patches = torch::mm(input_flat, weight_mat);
    // Make contiguous for kernel access
    patches = patches.contiguous();

    // Output initialized to zero
    auto output = torch::zeros({N, Cout, H_out, W_out}, input.options());

    int total = N * H_in * W_in * Cout * 9;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    fold_patches_kernel<<<blocks, threads>>>(
        patches.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, Cout, H_in, W_in, H_out, W_out
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a transposed 2D convolution with asymmetric input and a square kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the square convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            output_padding (int, optional): Additional size added to one side of the output shape. Defaults to 0.
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
