CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv_transpose2d_k3s1_tiled_forward(torch::Tensor input, torch::Tensor weight);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose2d_k3s1_tiled_forward", &conv_transpose2d_k3s1_tiled_forward,
          "Tiled gather transposed conv2d k=3 s=1 p=0 (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tiled gather kernel for transposed conv2d: kernel=3, stride=1, padding=0
// Output shape: (N, Cout, H_in+2, W_in+2)
// Each block covers a spatial tile of the output and a slice of output channels.
// Threads cooperatively load input halo + weights into shared memory.

#define TILE_H 8
#define TILE_W 16
#define OUT_CH_TILE 4
#define KS 3

__global__ void __launch_bounds__(TILE_H * TILE_W, 4)
conv_transpose2d_k3s1_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int Cout,
    int H_in, int W_in,
    int H_out, int W_out
) {
    // Grid: (ceil(W_out/TILE_W), ceil(H_out/TILE_H), N * ceil(Cout/OUT_CH_TILE))
    const int tile_x = blockIdx.x * TILE_W;
    const int tile_y = blockIdx.y * TILE_H;
    const int nc_idx = blockIdx.z;
    const int n       = nc_idx / ((Cout + OUT_CH_TILE - 1) / OUT_CH_TILE);
    const int co_tile = nc_idx % ((Cout + OUT_CH_TILE - 1) / OUT_CH_TILE);
    const int co_base = co_tile * OUT_CH_TILE;

    const int tx = threadIdx.x % TILE_W;  // local output col
    const int ty = threadIdx.x / TILE_W;  // local output row

    const int out_x = tile_x + tx;
    const int out_y = tile_y + ty;

    // Each thread accumulates OUT_CH_TILE output values
    float acc[OUT_CH_TILE];
    #pragma unroll
    for (int k = 0; k < OUT_CH_TILE; k++) acc[k] = 0.0f;

    // Input halo tile dimensions: TILE_H + KS - 1 by TILE_W + KS - 1
    // But for transposed conv (stride=1, padding=0):
    //   output[oh, ow] += input[oh - kh, ow - kw] * weight[ci, co, kh, kw]
    //   valid if: 0 <= oh-kh < H_in => oh-kh in [0, H_in)
    // So we need input rows [tile_y-2 .. tile_y+TILE_H-1], clamped to [0, H_in)
    const int HALO_H = TILE_H + KS - 1;  // 10
    const int HALO_W = TILE_W + KS - 1;  // 18

    // We process Cin in chunks to keep shared memory modest
    // smem layout: [CI_CHUNK][HALO_H][HALO_W] input tile +
    //              [CI_CHUNK][OUT_CH_TILE][KS][KS] weights
    const int CI_CHUNK = 8;
    // input tile: 8 * 10 * 18 = 1440 floats = 5760 bytes
    // weight tile: 8 * 4 * 3 * 3 = 288 floats = 1152 bytes
    // total: ~6912 bytes << 48KB OK
    __shared__ float smem_in[CI_CHUNK][HALO_H][HALO_W + 1];  // +1 to avoid bank conflicts
    __shared__ float smem_w[CI_CHUNK][OUT_CH_TILE][KS][KS];

    const int threads = TILE_H * TILE_W;  // 128
    const int tid = threadIdx.x;

    for (int ci_base = 0; ci_base < Cin; ci_base += CI_CHUNK) {
        int ci_end = ci_base + CI_CHUNK;
        if (ci_end > Cin) ci_end = Cin;
        int ci_count = ci_end - ci_base;

        // Cooperatively load input halo tile
        // Total elements: ci_count * HALO_H * HALO_W
        int halo_total = ci_count * HALO_H * HALO_W;
        for (int i = tid; i < halo_total; i += threads) {
            int ci_local = i / (HALO_H * HALO_W);
            int rem      = i % (HALO_H * HALO_W);
            int hy       = rem / HALO_W;
            int hx       = rem % HALO_W;
            // output row tile_y maps to input row tile_y-2 (since kh in [0,2])
            int in_y = (tile_y - (KS - 1)) + hy;  // = tile_y - 2 + hy
            int in_x = (tile_x - (KS - 1)) + hx;
            int ci   = ci_base + ci_local;
            float val = 0.0f;
            if (ci < Cin && in_y >= 0 && in_y < H_in && in_x >= 0 && in_x < W_in) {
                val = __ldg(&input[((n * Cin + ci) * H_in + in_y) * W_in + in_x]);
            }
            smem_in[ci_local][hy][hx] = val;
        }

        // Cooperatively load weight tile: [ci_base..ci_end] x [co_base..co_base+OUT_CH_TILE] x [3][3]
        // weight layout: [Cin, Cout, KS, KS] (PyTorch ConvTranspose2d stores [Cin, Cout/groups, kH, kW])
        int w_total = ci_count * OUT_CH_TILE * KS * KS;
        for (int i = tid; i < w_total; i += threads) {
            int ci_local = i / (OUT_CH_TILE * KS * KS);
            int rem      = i % (OUT_CH_TILE * KS * KS);
            int co_local = rem / (KS * KS);
            int kk       = rem % (KS * KS);
            int kh = kk / KS;
            int kw = kk % KS;
            int ci = ci_base + ci_local;
            int co = co_base + co_local;
            float val = 0.0f;
            if (ci < Cin && co < Cout) {
                // weight[ci, co, kh, kw]
                val = __ldg(&weight[((ci * Cout + co) * KS + kh) * KS + kw]);
            }
            smem_w[ci_local][co_local][kh][kw] = val;
        }

        __syncthreads();

        // Each thread computes its output pixel for all output channels in tile
        if (out_y < H_out && out_x < W_out) {
            // halo offset: for this thread, local halo coords are:
            // hy_base = ty + (KS-1) = ty + 2  (center of halo for this output)
            // but we need to sum over kh in [0, KS-1]:
